import{_ as a,b as e,c as d,I as r}from"./chunks/framework.C6cPs9Ia.js";const m=JSON.parse('{"title":"周末去了趟猫咖","description":"高中生的周末猫咖探店记录——一小时撸猫体验报告","frontmatter":{"title":"周末去了趟猫咖","date":"2026-09-14T00:00:00.000Z","tags":["猫咖","日常","探店"],"cover":"/LQY/images/moment-2.jpg","head":[["meta",{"name":"description","content":"高中生的周末猫咖探店记录——一小时撸猫体验报告"}],["meta",{"name":"keywords","content":"猫咖, 探店, 撸猫, 周末日常"}]]},"headers":[],"relativePath":"posts/ba-diary.md","filePath":"posts/ba-diary.md"}'),o={name:"posts/ba-diary.md"};function i(l,t,p,s,n,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<p>家里没条件养猫，所以每个月的零花钱里有一项固定预算：猫咖。这周末的额度兑现了，写个记录。</p><hr><h2 id="门店初印象" tabindex="-1">门店初印象 <a class="header-anchor" href="#门店初印象" aria-label="Permalink to &quot;门店初印象&quot;">​</a></h2><p>这家店在学校相反方向的老小区里，要穿过两条梧桐树夹道的巷子。推开门，风铃一响，七八只猫的视线齐刷刷投过来，然后就各自继续干各自的事了，很有一副&quot;见过世面&quot;的样子。</p><p>店内是原木色装修加猫爬架，落地窗边的位置最好——阳光斜进来的时候，猫会自己流动到那里，排成一排晒太阳。</p><h2 id="猫咪点名" tabindex="-1">猫咪点名 <a class="header-anchor" href="#猫咪点名" aria-label="Permalink to &quot;猫咪点名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>猫</th><th>特征</th><th>表现</th></tr></thead><tbody><tr><td>橘座（橘猫）</td><td>很重</td><td>趴在门口一动不动，用尾巴当门槛</td></tr><tr><td>团子（白猫）</td><td>精力旺盛</td><td>逗猫棒响应速度极快，非常敬业</td></tr><tr><td>墨汁（黑猫）</td><td>很低调</td><td>藏在书架后面偷袭逗猫棒</td></tr><tr><td>麻薯（三花）</td><td>睡神</td><td>全程睡觉，但睡姿很可爱</td></tr></tbody></table><h2 id="今日高光" tabindex="-1">今日高光 <a class="header-anchor" href="#今日高光" aria-label="Permalink to &quot;今日高光&quot;">​</a></h2><p>给团子喂冻干的时候，它吃完没有走，站在我手边，把脑袋往我掌心里顶了一下。</p><p>就一下。</p><p>一个星期的疲惫全清零了。什么函数什么受力分析，那个瞬间全都往后排。</p><p>旁边的小朋友问她妈：&quot;那个人为什么在傻笑？&quot;</p><p>对不起，不是傻笑，是充电。</p><h2 id="小账本" tabindex="-1">小账本 <a class="header-anchor" href="#小账本" aria-label="Permalink to &quot;小账本&quot;">​</a></h2><ul><li>入场券（含一杯饮品）：零花钱的 40%</li><li>冻干一包：15%</li><li>猫爪拉花咖啡：好看到下不去嘴，但还是喝了</li></ul><div class="tip custom-block"><p class="custom-block-title">探店结论</p><p>人均消费可控，猫咪们很敬业，回去的公交上满身猫毛。一个月来一次，值回票价。</p></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>回家路上在想，猫这种动物最大的本事，可能就是让一个大人能在一小时内彻底不想任何正事。就冲这个，这钱花得不亏。</p><p>下个月还来，目标：攻略墨汁。</p><p>（照片就不放了，拍猫三小时，出片三张，全部糊的。设备问题，绝对不是技术问题。）</p>',20)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
